import Dashboard from './components/Dashboard';
import MaterialsEntry from './components/MaterialsEntry';
import DefectsList from './components/DefectsList';
import { Tab } from './types';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<Tab>(Tab.DASHBOARD);

  const renderContent = () => {
    switch (activeTab) {
      case Tab.GENERAL:
        return <GeneralInfo />;
      case Tab.DASHBOARD:
        return <Dashboard />;
      case Tab.MATERIALS:
        return <MaterialsEntry />;
      case Tab.DEFECTS:
