import { GoogleGenAI } from "@google/genai";
import { WeatherData } from '../types';

export const fetchWeatherForecast = async (): Promise<WeatherData[]> => {
  // Check both process.env (for legacy/test) and import.meta.env (for Vite)
  const apiKey = import.meta.env?.VITE_API_KEY || process.env.API_KEY;

  if (!apiKey) {
    console.warn("API_KEY is missing. Returning mock weather data.");
    return mockWeatherData;
  }

  try {
    const ai = new GoogleGenAI({ apiKey: apiKey });

    // We request data starting from 3 days ago to ensure today is at index 3 (4th position)
    const prompt = `
      Search for the weather in District 7, Ho Chi Minh City for a 10-day period starting from 3 days ago.
      Return a summary list.
      Strictly format the output as a JSON array where each object has these keys:
      - "date": string (e.g., "Mon, 01/01")
      - "temp": string (e.g., "24°C - 32°C")
      - "condition": string (e.g., "Sunny", "Rainy", "Cloudy")
      Do not include any markdown formatting like \`\`\`json. Just the raw JSON string.
    `;

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
      },
    });

    const text = response.text || "";

    // Attempt to clean and parse JSON
    const cleanedText = text.replace(/```json/g, '').replace(/```/g, '').trim();
    const data = JSON.parse(cleanedText);

    if (Array.isArray(data)) {
        return data.slice(0, 10);
    }
    throw new Error("Invalid format");

  } catch (error) {
    console.error("Failed to fetch weather from Gemini:", error);
    return mockWeatherData;
  }
};

const mockWeatherData: WeatherData[] = Array.from({ length: 10 }).map((_, i) => {
    const d = new Date();
    // Start from 3 days ago
    d.setDate(d.getDate() + i - 3);
    return {
        date: d.toLocaleDateString('vi-VN', { day: '2-digit', month: '2-digit' }),
        temp: `${24 + Math.round(Math.random() * 5)}°C - ${30 + Math.round(Math.random() * 5)}°C`,
        condition: Math.random() > 0.5 ? "Nắng" : "Mưa",
    };
});

