const getManpowerData = () => {
    // Lấy 10 dòng cuối cùng từ dữ liệu sheet
    const last10DaysData = rawSheetData.slice(-10);
    const today = new Date();

    return last10DaysData.map((data, index) => {
        // Tính ngày ngược từ hôm nay
        // Index 9 (cuối mảng) = Hôm nay
        // Index 0 (đầu mảng cắt) = 9 ngày trước
        const date = new Date(today);
        date.setDate(today.getDate() - (9 - index));
        return {
            date: date.toLocaleDateString('vi-VN', { day: '2-digit', month: '2-digit' }),
            workers: data.w,
            engineers: data.e
        };
    });
};

