const API_KEY = process.env.API_KEY;
const BASE_URL = 'https://sheets.googleapis.com/v4/spreadsheets';

export interface SheetData {
    d800: any[];
    payment: any[];
    manpower: any[];
}

// Helper to parse numeric values safely
const parseNum = (val: string | undefined | null) => {
    if (!val || val === '') return null;
    const cleanVal = String(val).replace(/,/g, '').replace(/%/g, '');
    const num = parseFloat(cleanVal);
    return isNaN(num) ? null : num;
};

// Helper to calculate difference
const calcDiff = (plan: number | null, actual: number | null) => {
    if (plan === null || actual === null) return null;
    return actual - plan;
};

export const fetchDashboardData = async (): Promise<SheetData | null> => {
    if (!API_KEY || !GOOGLE_SHEET_ID) {
        console.warn("Missing API Key or Sheet ID");
        return null;
    }

    try {
        // Fetch 3 ranges simultaneously: D800, Payment, Manpower
        // CHANGED: Removed row limit (e.g., D50) to fetch ALL available data rows
        const ranges = ['D800!A2:D', 'Payment!A2:C', 'Manpower!A2:C'];
        const url = `${BASE_URL}/${GOOGLE_SHEET_ID}/values:batchGet?key=${API_KEY}&ranges=${ranges.join('&ranges=')}`;

        const response = await fetch(url);
        if (!response.ok) {
            throw new Error(`Sheets API Error: ${response.statusText}`);
        }

        const data = await response.json();
        const valueRanges = data.valueRanges;

        if (!valueRanges || valueRanges.length < 3) return null;

        // Process D800 Data (Index 0)
        // Col A: Date, B: Plan, C: Actual, D: Forecast
        const d800Raw = valueRanges[0].values || [];
        const d800 = d800Raw
            .filter((row: string[]) => row && row[0]) // Filter empty rows or rows without date
            .map((row: string[]) => {
                const plan = parseNum(row[1]);
                const actual = parseNum(row[2]);
                return {
                    date: row[0],
                    plan: plan,
                    actual: actual,
                    forecast: parseNum(row[3]),
                    diff: calcDiff(plan, actual)
                };
            });

        // Process Payment Data (Index 1)
        // Col A: Date, B: Progress, C: Payment
        const paymentRaw = valueRanges[1].values || [];
        const payment = paymentRaw
            .filter((row: string[]) => row && row[0])
            .map((row: string[]) => ({
                date: row[0],
                progress: parseNum(row[1]),
                payment: parseNum(row[2])
            }));

        // Process Manpower Data (Index 2)
        // Col A: Date, B: Workers, C: Engineers
        const manpowerRaw = valueRanges[2].values || [];
        const manpower = manpowerRaw
            .filter((row: string[]) => row && row[0])
            .map((row: string[]) => ({
                date: row[0],
                workers: parseNum(row[1]),
                engineers: parseNum(row[2])
            }));

        return {
            d800,
            payment,
            manpower
        };

    } catch (error) {
        console.error("Failed to fetch Google Sheets data:", error);
        return null;
    }
};

