        // 2. Payment: Tab 'Tiến độ Thanh toán', range A1:C48 (Includes header A1 potentially)
        // 3. Manpower: Tab 'D800', range A67:D114
        const ranges = [
            'D800!A2:E49', 
            'Tiến độ Thanh toán!A1:C48', 
            'D800!A67:D114'
        ];

        const encodedRanges = ranges.map(r => encodeURIComponent(r));
        const url = `${BASE_URL}/${GOOGLE_SHEET_ID}/values:batchGet?key=${API_KEY}&ranges=${encodedRanges.join('&ranges=')}`;

        const response = await fetch(url);
        if (!response.ok) {
            throw new Error(`Sheets API Error: ${response.statusText}`);
