// Custom Label Component
const CustomLabel = (props: any) => {
  const { x, y, value, index, lastValidIndex, color } = props;

  // Show label only if this is the last valid index for the series
  if (index === lastValidIndex && value !== null && value !== undefined) {
    return (
      <text x={x} y={y} dy={-10} fill={color} fontSize={12} fontWeight="bold" textAnchor="middle">
        {Number(value).toFixed(1)}%
      </text>
    );
  }
  return null;
};

