import { GOOGLE_SHEET_ID } from '../constants';

// We switch to the Public CSV export endpoint.
// This works for any sheet set to "Anyone with the link can view".
// It requires NO API Key, avoiding 403/400 errors.
const BASE_URL = `https://docs.google.com/spreadsheets/d/${GOOGLE_SHEET_ID}/gviz/tq?tqx=out:csv`;

export interface SheetData {
    d800: any[];
    payment: any[];
    manpower: any[];
}

// Helper to parse numeric values safely from CSV strings
const parseNum = (val: string | undefined | null) => {
    if (!val || val.trim() === '') return null;

    // Remove quotes if present (CSV export adds quotes to strings)
    let cleanVal = val.replace(/^"|"$/g, '').trim();

    // Remove % and trim
    cleanVal = cleanVal.replace(/%/g, '').trim();

    // Handle Vietnamese/European style: 19,5 -> 19.5
    if (cleanVal.includes(',') && !cleanVal.includes('.')) {
        cleanVal = cleanVal.replace(',', '.');
    }

    // Remove thousands separators (e.g. 1,000 -> 1000) if mixed with dots
    // Simple heuristic: remove commas
    cleanVal = cleanVal.replace(/,/g, '');

    const num = parseFloat(cleanVal);
    return isNaN(num) ? null : num;
};

// Helper to clean CSV cell strings (remove quotes)
const cleanStr = (val: string | undefined) => {
    if (!val) return '';
    return val.replace(/^"|"$/g, '').trim();
};

// Robust CSV Line Parser to handle commas inside quotes (e.g. "1,200")
const parseCSVLine = (text: string): string[] => {
    const result: string[] = [];
    let startValueIndex = 0;
    let inQuotes = false;

    for (let i = 0; i < text.length; i++) {
        if (text[i] === '"') {
            inQuotes = !inQuotes;
        } else if (text[i] === ',' && !inQuotes) {
            result.push(text.substring(startValueIndex, i));
            startValueIndex = i + 1;
        }
    }
    result.push(text.substring(startValueIndex));
    return result;
};

const fetchSheetCSV = async (sheetName: string, range: string) => {
    try {
        // Construct the URL for CSV export
        // sheet: Tab name
        // range: A2:E49
        const url = `${BASE_URL}&sheet=${encodeURIComponent(sheetName)}&range=${encodeURIComponent(range)}`;

        const response = await fetch(url);
        if (!response.ok) throw new Error(`Failed to fetch ${sheetName}`);

        const text = await response.text();

        // Split by new line and parse CSV
        const rows = text.split('\n').map(parseCSVLine);
        return rows;
    } catch (error) {
        console.error(`Error fetching CSV for ${sheetName}:`, error);
        return [];
    }
};

export const fetchDashboardData = async (): Promise<SheetData | null> => {
    if (!GOOGLE_SHEET_ID) {
        console.warn("Missing Sheet ID");
        return null;
    }

    try {
        // Fetch 3 ranges in parallel
        const [d800Raw, paymentRaw, manpowerRaw] = await Promise.all([
            fetchSheetCSV('D800', 'A2:E49'),
            fetchSheetCSV('Tiến độ Thanh toán', 'A2:C48'), // Start from A2 to skip header logic if needed, but CSV usually handles it well
            fetchSheetCSV('D800', 'A67:D114')
        ]);

        if (!d800Raw.length && !paymentRaw.length && !manpowerRaw.length) return null;

        // --- Process D800 Data ---
        const d800 = d800Raw
            .filter(row => row.length > 0 && cleanStr(row[0])) 
            .map(row => {
                const plan = parseNum(row[1]);   // Col B
                const actual = parseNum(row[2]); // Col C

                // Correction: Col D is Diff (Gray), Col E is Forecast (Green Dashed)
                const colD = parseNum(row[3]);   // Col D
                const colE = row.length > 4 ? parseNum(row[4]) : null; // Col E

                return {
                    date: cleanStr(row[0]),
                    plan: plan,
                    actual: actual,
                    diff: colD,      // Map Col D to diff
                    forecast: colE   // Map Col E to forecast
                };
            })
            .filter(item => item.plan !== null || item.actual !== null || item.forecast !== null || item.diff !== null);


        // --- Process Payment Data ---
        const payment = paymentRaw
            .filter(row => row.length > 0 && cleanStr(row[0]))
            .map(row => ({
                date: cleanStr(row[0]),
                progress: parseNum(row[1]),
                payment: parseNum(row[2])
            }))
            // Keep all rows that have a date, even if progress/payment is null.
            // This ensures the chart X-axis extends to the end of the planned timeline.
            .filter(item => item.date);


        // --- Process Manpower Data ---
        const manpower = manpowerRaw
            .filter(row => row.length > 0 && cleanStr(row[0]))
            .map(row => ({
                date: cleanStr(row[0]),
                workers: parseNum(row[1]),   // Col B
                engineers: parseNum(row[2])  // Col C
            }))
            .filter(item => item.workers !== null || item.engineers !== null);

        return {
            d800,
            payment,
            manpower
        };

    } catch (error) {
        console.error("Failed to fetch Google Sheets data:", error);
        return null;
    }
};

