    const lower = condition.toLowerCase();
    if (lower.includes('rain') || lower.includes('mưa')) return <CloudRain className="w-8 h-8 text-blue-500" />;
    if (lower.includes('sunny') || lower.includes('nắng') || lower.includes('clear')) return <Sun className="w-8 h-8 text-yellow-500" />;
    return <CloudSun className="w-8 h-8 text-slate-400" />;
  };

  // Helper to find last valid index for custom label
  const getLastValidIndex = (data: any[], key: string) => {
      for (let i = data.length - 1; i >= 0; i--) {
          if (data[i][key] !== null && data[i][key] !== undefined) return i;
      }
      return -1;
  };

