  const lastActualVal = lastD800ActualIndex >= 0 ? Number(d800Data[lastD800ActualIndex].actual) : 0;
  const lastDiffVal = lastD800DiffIndex >= 0 ? Number(d800Data[lastD800DiffIndex].diff) : 0;
  const totalPiles = 353;

  const calculatedPlanPercent = ((lastActualVal + lastDiffVal + 145) / totalPiles) * 100;
