    <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 flex items-start justify-between hover:shadow-md transition-shadow">
        <div>
            <p className="text-sm font-medium text-slate-500 mb-1">{title}</p>
            <h3 className="text-3xl font-bold text-slate-800 tracking-tight">{value}</h3>
            {subtext && (
                <p className={`text-sm mt-2 font-medium flex items-center gap-1 ${
                    trend === 'up' ? 'text-green-600' : trend === 'down' ? 'text-rose-600' : 'text-slate-500'
                }`}>
                    {trend === 'down' && <TrendingUp className="w-3 h-3 rotate-180" />}
                    {trend === 'up' && <TrendingUp className="w-3 h-3" />}
                    {subtext}
                </p>
            )}
        </div>
        <div className={`p-3 rounded-xl shadow-lg shadow-blue-900/5 ${color}`}>
            {icon}
        </div>
    </div>
)

export default Dashboard;

