                {trend === 'down' && <TrendingUp className="w-3 h-3 rotate-180" />}
                {trend === 'up' && <TrendingUp className="w-3 h-3" />}
                {subtext}
            </p>
        </div>
        <div className={`p-3 rounded-xl shadow-lg shadow-blue-900/5 ${color}`}>
            {icon}
        </div>
    </div>
)

