import React from 'react';
import { 
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  BarChart, Bar, Legend, ComposedChart, Line, ReferenceLine, LabelList 
} from 'recharts';
import { CloudSun, TrendingUp, AlertOctagon, Wallet, CloudRain, Sun, Calendar, RefreshCw } from 'lucide-react';
import { WeatherData } from '../types';
import { SheetData } from '../services/sheetsService';

// Default Fallback Data (used if API fails or loading)
const defaultD800Data = [
  { date: '28/12', plan: 0, actual: 0, diff: 0, forecast: null },
  { date: '30/12', plan: 10, actual: 0, diff: -10, forecast: null },
  { date: '01/01', plan: 20, actual: 2, diff: -18, forecast: null },
  { date: '03/01', plan: 30, actual: 3, diff: -27, forecast: null },
  { date: '05/01', plan: 45, actual: 4, diff: -41, forecast: null },
  { date: '07/01', plan: 55, actual: 7, diff: -48, forecast: null },
  { date: '09/01', plan: 65, actual: 14, diff: -51, forecast: null },
  { date: '11/01', plan: 75, actual: 25, diff: -50, forecast: null },
  { date: '13/01', plan: 85, actual: 32, diff: -53, forecast: null },
  { date: '15/01', plan: 95, actual: 41, diff: -54, forecast: 41 },
];

const defaultPaymentData = [
  { date: '28/12/2025', progress: 0.0, payment: 10.0 },
  { date: '14/01/2026', progress: 20.0, payment: 10.0 },
];

const defaultManpowerData = [
  { date: '01/01', workers: 120, engineers: 15 },
  { date: '02/01', workers: 125, engineers: 15 },
];

// Custom Label Component
const CustomLabel = (props: any) => {
  const { x, y, value, index, lastValidIndex, color, unit } = props;

  // Show label only if this is the last valid index for the series
  if (index === lastValidIndex && value !== null && value !== undefined) {
    return (
      <text x={x} y={y} dy={-10} fill={color} fontSize={12} fontWeight="bold" textAnchor="middle">
        {Number(value).toFixed(1)}{unit || ''}
      </text>
    );
  }
  return null;
};

interface DashboardProps {
    weather: WeatherData[];
    sheetData: SheetData | null;
    loading: boolean;
    error: boolean;
}

const Dashboard: React.FC<DashboardProps> = ({ weather, sheetData, loading, error }) => {

  // Prepare data (Use Props -> Fallback to Defaults)
  // We use defaults if sheetData is null (error/loading) or if specific arrays are empty
  const d800Data = sheetData?.d800 && sheetData.d800.length > 0 ? sheetData.d800 : defaultD800Data;
  const paymentData = sheetData?.payment && sheetData.payment.length > 0 ? sheetData.payment : defaultPaymentData;
  const manpowerData = sheetData?.manpower && sheetData.manpower.length > 0 
        ? sheetData.manpower.slice(-10) // Ensure logic matches previous implementation
        : defaultManpowerData;

  const getWeatherIcon = (condition: string) => {
    const lower = condition.toLowerCase();
    if (lower.includes('rain') || lower.includes('mưa')) return <CloudRain className="w-8 h-8 text-blue-500" />;
    if (lower.includes('sunny') || lower.includes('nắng') || lower.includes('clear')) return <Sun className="w-8 h-8 text-yellow-500" />;
    return <CloudSun className="w-8 h-8 text-slate-400" />;
  };

  // Helper to find last valid index for custom label
  const getLastValidIndex = (data: any[], key: string) => {
      for (let i = data.length - 1; i >= 0; i--) {
          if (data[i][key] !== null && data[i][key] !== undefined) return i;
      }
      return -1;
  };

  const lastProgressIndex = getLastValidIndex(paymentData, 'progress');
  const lastPaymentIndex = getLastValidIndex(paymentData, 'payment');

  const lastD800PlanIndex = getLastValidIndex(d800Data, 'plan');
  const lastD800ActualIndex = getLastValidIndex(d800Data, 'actual');
  const lastD800ForecastIndex = getLastValidIndex(d800Data, 'forecast');
  const lastD800DiffIndex = getLastValidIndex(d800Data, 'diff');

  // --- KPI Calculations ---

  // 1. % Hoàn Thành Cọc (From Payment Chart - 'progress')
  const currentCompletion = lastProgressIndex >= 0 ? Number(paymentData[lastProgressIndex].progress) : 0;

  // 2. Delay Calculation
  // Requested Formula: % Hoàn Thành Cọc - ((Lũy kế thực tế D800 + Chênh lệch D800 + 145) / 353 * 100)
  const lastActualVal = lastD800ActualIndex >= 0 ? Number(d800Data[lastD800ActualIndex].actual) : 0;
  const lastDiffVal = lastD800DiffIndex >= 0 ? Number(d800Data[lastD800DiffIndex].diff) : 0;
  const totalPiles = 353;

  const calculatedPlanPercent = ((lastActualVal + lastDiffVal + 145) / totalPiles) * 100;
  const kpiDiff = currentCompletion - calculatedPlanPercent;

  // If kpiDiff is negative, it means Completion < Plan -> Behind Schedule (Chậm)
  // If kpiDiff is positive, it means Completion > Plan -> Ahead of Schedule (Vượt)
  const isBehind = kpiDiff < 0;

  return (
    <div className="p-4 md:p-8 max-w-7xl mx-auto space-y-8 flex flex-col min-h-full">

      {/* KPI Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <KPICard 
          title="% Hoàn Thành Cọc" 
          value={`${currentCompletion.toFixed(1)}%`} 
          subtext={isBehind 
            ? `Chậm ${Math.abs(kpiDiff).toFixed(1)}% so với KH` 
            : `Vượt ${kpiDiff.toFixed(1)}% so với KH`
          } 
          trend={isBehind ? "down" : "up"} // Down (Red) = Bad/Delay, Up (Green) = Good/Ahead
          icon={<TrendingUp className="text-white w-6 h-6"/>}
          color={isBehind ? "bg-rose-600" : "bg-blue-600"} // Red if delayed
        />
        <KPICard 
          title="Giá Trị Thanh Toán" 
          value="4.55 Tỷ" 
          subtext="Đợt 2 - Đang chờ duyệt" 
          trend="neutral" 
          icon={<Wallet className="text-white w-6 h-6"/>}
          color="bg-emerald-600"
        />
        <KPICard 
          title="Rủi ro" 
          value="4" 
          subtext="2 Major, 2 Minor" 
          trend="down" 
          icon={<AlertOctagon className="text-white w-6 h-6"/>}
          color="bg-rose-600"
        />
      </div>

      {/* Loading / Error Indicator for Sheets */}
      {loading && (
          <div className="flex items-center gap-2 text-sm text-blue-600 bg-blue-50 p-2 rounded-lg w-fit animate-pulse">
              <RefreshCw className="w-4 h-4 animate-spin"/> Đang cập nhật dữ liệu từ Google Sheets...
          </div>
      )}
      {error && !loading && (
          <div className="flex items-center gap-2 text-sm text-red-600 bg-red-50 p-2 rounded-lg w-fit">
              <AlertOctagon className="w-4 h-4"/> Không thể tải dữ liệu mới. Đang hiển thị dữ liệu mẫu. (Kiểm tra API Key/Sheet ID)
          </div>
      )}

      {/* Chart Section */}
      <div className="flex flex-col gap-8">
            {/* D800 Progress Chart */}
            <div className="bg-white p-4 md:p-6 rounded-xl shadow-sm border border-slate-200 w-full overflow-hidden">
                <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-2">
                    <h3 className="font-bold text-slate-800 text-lg">Biểu đồ tiến độ cọc D800</h3>
                    <span className="text-sm text-slate-500 bg-slate-100 px-3 py-1 rounded-full">Đơn vị: Tim cọc</span>
                </div>

                <div className="h-[300px] md:h-[400px] w-full">
                    <ResponsiveContainer width="100%" height="100%">
                        <ComposedChart data={d800Data} margin={{ top: 20, right: 10, left: -20, bottom: 0 }}>
                            <CartesianGrid strokeDasharray="3 3" vertical={true} />
                            <XAxis dataKey="date" tick={{fontSize: 12}} />
                            <YAxis tick={{fontSize: 12}} />
                            <Tooltip labelStyle={{ color: '#1e293b' }} />
                            <Legend verticalAlign="bottom" height={36} wrapperStyle={{fontSize: '12px'}}/>
                            <ReferenceLine y={0} stroke="#000" />

                            {/* Forecast - Green Dashed (Col E) */}
                            <Line 
                                type="monotone" 
                                dataKey="forecast" 
                                stroke="#10b981" 
                                strokeWidth={2}
                                strokeDasharray="5 5"
                                dot={false}
                                name="Dự kiến" 
                            >
                                <LabelList 
                                    content={
                                        <CustomLabel 
                                            color="#10b981" 
                                            lastValidIndex={lastD800ForecastIndex} 
                                        />
                                    } 
                                    dataKey="forecast"
                                />
                            </Line>

                            {/* Plan - Blue (Lũy kế kế hoạch) */}
                            <Line 
                                type="monotone" 
