import React, { useState, useEffect } from 'react';
import { Menu } from 'lucide-react';
import Sidebar from './components/Sidebar';
import GeneralInfo from './components/GeneralInfo';
import Dashboard from './components/Dashboard';
import MaterialsEntry from './components/MaterialsEntry';
import DefectsList from './components/DefectsList';
import ModelHouse from './components/ModelHouse';
import { Tab, WeatherData } from './types';
import { PROJECT_NAME } from './constants';
import { fetchWeatherForecast } from './services/weatherService';
import { fetchDashboardData, SheetData } from './services/sheetsService';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<Tab>(Tab.DASHBOARD);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  // --- Lifted State from Dashboard ---
  const [weather, setWeather] = useState<WeatherData[]>([]);
  const [sheetData, setSheetData] = useState<SheetData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(false);

  // Fetch data once on mount
  useEffect(() => {
    const loadData = async () => {
        setLoading(true);

        // Parallel fetching
        const [weatherRes, sheetRes] = await Promise.all([
            fetchWeatherForecast(),
            fetchDashboardData()
        ]);

        setWeather(weatherRes);

        if (sheetRes) {
            setSheetData(sheetRes);
            setError(false);
        } else {
            console.warn("Using default data due to sheet fetch failure.");
            setError(true);
        }
        setLoading(false);
    };

    loadData();
  }, []);

  const renderContent = () => {
    switch (activeTab) {
      case Tab.GENERAL:
        return <GeneralInfo />;
      case Tab.DASHBOARD:
        return (
            <Dashboard 
                weather={weather}
                sheetData={sheetData}
                loading={loading}
                error={error}
            />
        );
      case Tab.MATERIALS:
        return <MaterialsEntry />;
      case Tab.DEFECTS:
        return <DefectsList />;
      case Tab.MODEL_HOUSE:
        return <ModelHouse />;
      default:
        return (
            <Dashboard 
                weather={weather}
                sheetData={sheetData}
                loading={loading}
                error={error}
            />
        );
    }
  };

  return (
    <div className="flex min-h-screen bg-slate-50 overflow-x-hidden">
      {/* Mobile Header - Updated to slate-800 */}
      <div className="md:hidden fixed top-0 left-0 right-0 bg-slate-800 text-white z-40 px-4 py-3 flex items-center justify-between shadow-md">
        <div className="flex items-center gap-3">
             <button onClick={() => setIsSidebarOpen(true)} className="p-1">
                <Menu className="w-6 h-6" />
             </button>
             <span className="font-bold text-sm truncate">{PROJECT_NAME}</span>
        </div>
      </div>

      {/* Overlay for mobile sidebar */}
      {isSidebarOpen && (
        <div 
            className="fixed inset-0 bg-black/50 z-40 md:hidden"
            onClick={() => setIsSidebarOpen(false)}
        />
      )}

      {/* Sidebar - Passed props for mobile control */}
      <Sidebar 
        activeTab={activeTab} 
        setActiveTab={(tab) => {
            setActiveTab(tab);
            setIsSidebarOpen(false); // Close sidebar on selection (mobile)
        }} 
        isOpen={isSidebarOpen}
        onClose={() => setIsSidebarOpen(false)}
      />

      {/* Main Content */}
      <main className={`flex-1 min-w-0 transition-all duration-300 pt-14 md:pt-0 w-full ${isSidebarOpen ? 'overflow-hidden' : ''} md:ml-64`}>
        {renderContent()}
      </main>
    </div>
  );
};

export default App;

