import { GOOGLE_SHEET_ID } from '../constants';

// We switch to the Public CSV export endpoint.
const BASE_URL = `https://docs.google.com/spreadsheets/d/${GOOGLE_SHEET_ID}/gviz/tq?tqx=out:csv`;

export interface SheetData {
    d800: any[];
    payment: any[];
    manpower: any[];
    modelHouse: any[];
}

// Helper to parse numeric values safely from CSV strings
const parseNum = (val: string | undefined | null) => {
    if (!val || val.trim() === '') return null;

    // Remove quotes if present
    let cleanVal = val.replace(/^"|"$/g, '').trim();

    // Remove % and trim
    cleanVal = cleanVal.replace(/%/g, '').trim();

    // Handle Vietnamese style: 19,5 -> 19.5
    if (cleanVal.includes(',') && !cleanVal.includes('.')) {
        cleanVal = cleanVal.replace(',', '.');
    }

    cleanVal = cleanVal.replace(/,/g, '');

    const num = parseFloat(cleanVal);
    return isNaN(num) ? null : num;
};

// Helper to clean CSV cell strings
const cleanStr = (val: string | undefined) => {
    if (!val) return '';
    return val.replace(/^"|"$/g, '').trim();
};

// Robust CSV Line Parser
const parseCSVLine = (text: string): string[] => {
    const result: string[] = [];
    let startValueIndex = 0;
    let inQuotes = false;

    for (let i = 0; i < text.length; i++) {
        if (text[i] === '"') {
            inQuotes = !inQuotes;
        } else if (text[i] === ',' && !inQuotes) {
            result.push(text.substring(startValueIndex, i));
            startValueIndex = i + 1;
        }
    }
    result.push(text.substring(startValueIndex));
    return result;
};

const fetchSheetCSV = async (sheetName: string, range: string) => {
    try {
        const url = `${BASE_URL}&sheet=${encodeURIComponent(sheetName)}&range=${encodeURIComponent(range)}`;
        const response = await fetch(url);
        if (!response.ok) throw new Error(`Failed to fetch ${sheetName}`);
        const text = await response.text();
        const rows = text.split('\n').map(parseCSVLine);
        return rows;
    } catch (error) {
        console.error(`Error fetching CSV for ${sheetName}:`, error);
        return [];
    }
};

export const fetchDashboardData = async (): Promise<SheetData | null> => {
    if (!GOOGLE_SHEET_ID) return null;

    try {
        const [d800Raw, paymentRaw, manpowerRaw, modelHouseRaw] = await Promise.all([
            fetchSheetCSV('D800', 'A2:E49'),
            fetchSheetCSV('Tiến độ Thanh toán', 'A2:C48'),
            fetchSheetCSV('D800', 'A67:D114'),
            fetchSheetCSV('Nhà mẫu', 'A2:C7') // Range A2:C7 as requested
        ]);

        // Process D800
        const d800 = d800Raw
            .filter(row => row.length > 0 && cleanStr(row[0])) 
            .map(row => ({
                date: cleanStr(row[0]),
                plan: parseNum(row[1]),
                actual: parseNum(row[2]),
                diff: parseNum(row[3]),
                forecast: row.length > 4 ? parseNum(row[4]) : null
            }));

        // Process Payment
        const payment = paymentRaw
            .filter(row => row.length > 0 && cleanStr(row[0]))
            .map(row => ({
                date: cleanStr(row[0]),
                progress: parseNum(row[1]),
                payment: parseNum(row[2])
            }));

        // Process Manpower
        const manpower = manpowerRaw
            .filter(row => row.length > 0 && cleanStr(row[0]))
            .map(row => ({
                date: cleanStr(row[0]),
                workers: parseNum(row[1]),
                engineers: parseNum(row[2])
            }));

        // Process Model House Data
        const modelHouse = modelHouseRaw
            .filter(row => row.length >= 2 && cleanStr(row[0]))
            .map(row => ({
                month: cleanStr(row[0]),
                plan: parseNum(row[1]),
                actual: parseNum(row[2])
            }));

        return { d800, payment, manpower, modelHouse };

    } catch (error) {
        console.error("Failed to fetch Google Sheets data:", error);
        return null;
    }
};

