const FOLDER_ID = '1I4GCEJ_PoSmCA7AvOBCiAoN8xjlVH8f1';

export interface DriveFile {
  id: string;
  name: string;
  thumbnailLink: string;
}

export const fetchLatestDriveImages = async (): Promise<DriveFile[]> => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    console.warn("API_KEY is missing, cannot fetch Drive images.");
    return [];
  }

  try {
    // API v3: List files in folder, filter for images, sort by createdTime desc, limit to 9
    const query = `'${FOLDER_ID}' in parents and mimeType contains 'image/' and trashed = false`;
    const fields = 'files(id,name,thumbnailLink,createdTime)';
    const url = `https://www.googleapis.com/drive/v3/files?q=${encodeURIComponent(query)}&orderBy=createdTime desc&pageSize=9&fields=${encodeURIComponent(fields)}&key=${apiKey}`;

    const response = await fetch(url);
    if (!response.ok) {
      throw new Error(`Drive API responded with status: ${response.status}`);
    }

    const data = await response.json();
    return data.files || [];
  } catch (error) {
    console.error("Error fetching images from Google Drive:", error);
    return [];
  }
};

