  try {
    // Query: tệp nằm trong folder, là hình ảnh, không nằm trong thùng rác
    const query = `'${FOLDER_ID}' in parents and mimeType contains 'image/' and trashed = false`;
    // Fields: lấy ID, tên, link thumbnail và link xem trực tiếp
    const fields = 'files(id,name,thumbnailLink,webViewLink,createdTime)';
    const url = `https://www.googleapis.com/drive/v3/files?q=${encodeURIComponent(query)}&orderBy=createdTime desc&pageSize=9&fields=${encodeURIComponent(fields)}&key=${apiKey}`;

    const response = await fetch(url);

    if (!response.ok) {
      const errorData = await response.json();
      console.error("DRIVE_SERVICE_ERROR:", errorData);
      return [];
    }

    const data = await response.json();
    return data.files || [];
  } catch (error) {
    console.error("DRIVE_SERVICE_FETCH_FAILED:", error);
    return [];
  }
};

