const LastPointLabel = (props: any) => {
  const { x, y, value, index, lastValidIndex, color, unit, isInteger } = props;
  if (index === lastValidIndex && value !== null && value !== undefined) {
    const displayValue = isInteger ? Math.round(value) : Number(value).toFixed(1);
    return (
      <g>
        <circle cx={x} cy={y} r={5} fill={color} stroke="#fff" strokeWidth={2} />
