import React, { useState, useEffect, useCallback } from 'react';
import { Menu } from 'lucide-react';
import Sidebar from './components/Sidebar';
import GeneralInfo from './components/GeneralInfo';
import Dashboard from './components/Dashboard';
import MaterialsEntry from './components/MaterialsEntry';
import DefectsList from './components/DefectsList';
import ModelHouse from './components/ModelHouse';
import { Tab } from './types';
import { PROJECT_NAME } from './constants';
import { fetchDashboardData, SheetData } from './services/sheetsService';
import { fetchLatestDriveImages, DriveFile } from './services/driveService';
import { getCache, setCache, isCacheStale } from './services/cacheService';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<Tab>(Tab.DASHBOARD);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  // --- Global State ---
  const [sheetData, setSheetData] = useState<SheetData | null>(null);
  const [driveImages, setDriveImages] = useState<DriveFile[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(false);

  // Lazy Data Fetching Logic
  const loadDataForTab = useCallback(async (tab: Tab) => {
    // 1. Dashboard & Model House Tab Logic (Sheets)
    if (tab === Tab.DASHBOARD || tab === Tab.MODEL_HOUSE) {
      const cachedSheets = getCache('sheets');

      if (cachedSheets) {
        setSheetData(cachedSheets.data);
      }

      if (!cachedSheets || isCacheStale(cachedSheets.timestamp)) {
        if (!cachedSheets) setLoading(true);
        const res = await fetchDashboardData();
        if (res) {
          setSheetData(res);
          setCache('sheets', res);
          setError(false);
        } else if (!cachedSheets) {
          setError(true);
        }
        setLoading(false);
      }
    }

    // 2. Drive Images for Dashboard and Model House
    if (tab === Tab.MODEL_HOUSE || tab === Tab.DASHBOARD) {
      const cachedDrive = getCache('drive');
      if (cachedDrive) {
        setDriveImages(cachedDrive.data);
      }

      if (!cachedDrive || isCacheStale(cachedDrive.timestamp)) {
        const res = await fetchLatestDriveImages();
        if (res && res.length > 0) {
          setDriveImages(res);
          setCache('drive', res);
        }
      }
    }
  }, []);

  // Effect: Load data whenever active tab changes
  useEffect(() => {
    loadDataForTab(activeTab);
  }, [activeTab, loadDataForTab]);

  const renderContent = () => {
    switch (activeTab) {
      case Tab.GENERAL:
        return <GeneralInfo />;
      case Tab.DASHBOARD:
        return (
            <Dashboard 
                sheetData={sheetData}
                loading={loading}
                error={error}
                images={driveImages}
            />
        );
      case Tab.MATERIALS:
        return <MaterialsEntry />;
      case Tab.DEFECTS:
        return <DefectsList />;
      case Tab.MODEL_HOUSE:
        return (
          <ModelHouse 
            data={sheetData?.modelHouse || []} 
            images={driveImages}
            loading={loading} 
            error={error} 
          />
        );
      default:
        return <Dashboard sheetData={sheetData} loading={loading} error={error} images={driveImages} />;
    }
  };

  return (
    <div className="flex min-h-screen bg-slate-50 overflow-x-hidden">
      {/* Mobile Header */}
      <div className="md:hidden fixed top-0 left-0 right-0 bg-slate-800 text-white z-40 px-4 py-3 flex items-center justify-between shadow-md">
        <div className="flex items-center gap-3">
             <button onClick={() => setIsSidebarOpen(true)} className="p-1">
                <Menu className="w-6 h-6" />
             </button>
             <span className="font-bold text-sm truncate">{PROJECT_NAME}</span>
        </div>
      </div>

      {/* Overlay for mobile sidebar */}
      {isSidebarOpen && (
        <div 
            className="fixed inset-0 bg-black/50 z-40 md:hidden"
            onClick={() => setIsSidebarOpen(false)}
        />
      )}

      {/* Sidebar */}
      <Sidebar 
        activeTab={activeTab} 
        setActiveTab={(tab) => {
            setActiveTab(tab);
            setIsSidebarOpen(false); 
        }} 
        isOpen={isSidebarOpen}
        onClose={() => setIsSidebarOpen(false)}
      />

      {/* Main Content */}
      <main className={`flex-1 min-w-0 transition-all duration-300 pt-14 md:pt-0 w-full ${isSidebarOpen ? 'overflow-hidden' : ''} md:ml-64`}>
        {renderContent()}
      </main>
    </div>
  );
};

export default App;

