    const response = await fetch(url);

    if (!response.ok) {
      const errorData = await response.json();
      const message = errorData.error?.message || "Unknown Drive API Error";
      console.error("GOOGLE_DRIVE_API_ERROR:", message);

      // Throw specific error if key is invalid
      if (response.status === 400 && message.toLowerCase().includes("key not valid")) {
        throw new DriveApiError(400, "INVALID_KEY");
      }
      return [];
    }

    const data = await response.json();
    return data.files || [];
  } catch (error) {
