const FOLDER_ID = '1I4GCEJ_PoSmCA7AvOBCiAoN8xjlVH8f1';

export interface DriveFile {
  id: string;
  name: string;
  thumbnailLink: string;
  webViewLink?: string;
}

export class DriveApiError extends Error {
  constructor(public status: number, message: string, public code?: string) {
    super(message);
    this.name = 'DriveApiError';
  }
}

export const fetchLatestDriveImages = async (): Promise<DriveFile[]> => {
  // Always read from process.env.API_KEY at call time and trim it
  const rawKey = process.env.API_KEY;
  const apiKey = rawKey?.trim();

  if (!apiKey || apiKey === 'undefined' || apiKey.length < 10) {
    console.warn("DRIVE_SERVICE: No valid API_KEY found in environment.");
    return [];
  }

  try {
    const query = `'${FOLDER_ID}' in parents and mimeType contains 'image/' and trashed = false`;
    const fields = 'files(id,name,thumbnailLink,webViewLink,createdTime)';
    const url = `https://www.googleapis.com/drive/v3/files?q=${encodeURIComponent(query)}&orderBy=createdTime desc&pageSize=12&fields=${encodeURIComponent(fields)}&key=${apiKey}`;

    const response = await fetch(url);

    if (!response.ok) {
      const errorData = await response.json();
      const message = errorData.error?.message || "Unknown Drive API Error";
      const status = response.status;

      console.error("GOOGLE_DRIVE_API_ERROR:", message);

      // Handle "API key not valid"
      if (status === 400 && message.toLowerCase().includes("key not valid")) {
        throw new DriveApiError(400, "INVALID_KEY");
      }

      // Handle "API not enabled"
      if (message.toLowerCase().includes("has not been used") || message.toLowerCase().includes("disabled")) {
        throw new DriveApiError(403, "API_DISABLED");
      }

      return [];
    }

    const data = await response.json();
    return data.files || [];
  } catch (error) {
    if (error instanceof DriveApiError) throw error;
    console.error("DRIVE_SERVICE_FETCH_FAILED:", error);
    return [];
  }
};

