import { TRANSLATIONS } from '../constants';

const LastPointLabel = (props: any) => {
  const { x, y, value, index, lastValidIndex, color, unit, isInteger } = props;
  if (index === lastValidIndex && value !== null && value !== undefined) {
    const displayValue = isInteger ? Math.round(value) : Number(value).toFixed(1);
    return (
      <g>
        <circle cx={x} cy={y} r={5} fill={color} stroke="#fff" strokeWidth={2} />
        <text x={x} y={y} dy={-12} fill={color} fontSize={12} fontWeight="bold" textAnchor="middle">
          {displayValue}{unit || ''}
        </text>
      </g>
    );
  }
  return null;
};

interface DashboardProps {
    sheetData: SheetData | null;
    loading: boolean;
    error: boolean;
    language: Language;
}

const Dashboard: React.FC<DashboardProps> = ({ sheetData, loading, error, language }) => {
  const t = (key: string) => TRANSLATIONS[language][key] || key;
  const d800Data = sheetData?.d800 && sheetData.d800.length > 0 ? sheetData.d800 : [];
  const paymentData = sheetData?.payment && sheetData.payment.length > 0 ? sheetData.payment : [];
  const manpowerData = sheetData?.manpower && sheetData.manpower.length > 0 ? sheetData.manpower.slice(-15) : [];

  const driveFolderUrl = "https://drive.google.com/drive/folders/15UU8t5KK-2tbgwBxjex2A1nuCHBDeB2l?usp=sharing";

  const getLastValidIndex = (data: any[], key: string) => {
      for (let i = data.length - 1; i >= 0; i--) {
          if (data[i][key] !== null && data[i][key] !== undefined) return i;
      }
      return -1;
  };

  const lastProgressIndex = getLastValidIndex(paymentData, 'progress');
  const lastD800PlanIndex = getLastValidIndex(d800Data, 'plan');
  const lastD800ActualIndex = getLastValidIndex(d800Data, 'actual');
  const lastD800ForecastIndex = getLastValidIndex(d800Data, 'forecast');

  const currentCompletion = lastProgressIndex >= 0 ? Number(paymentData[lastProgressIndex].progress) : 0;
  const lastActualVal = lastD800ActualIndex >= 0 ? Number(d800Data[lastD800ActualIndex].actual) : 0;
  const lastDiffVal = lastD800ActualIndex >= 0 ? (d800Data[lastD800ActualIndex].diff || 0) : 0;

  const totalPiles = 353;
  const targetProgress = ((lastActualVal + Math.abs(lastDiffVal) + 145) / totalPiles) * 100;
  const kpiDiff = currentCompletion - targetProgress;

  return (
    <div className="p-4 md:p-8 max-w-7xl mx-auto space-y-8 flex flex-col min-h-full animate-fade-in pb-20">

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <KPICard 
          title={t('piles_completion')} 
          value={`${currentCompletion.toFixed(1)}%`} 
          subtext={kpiDiff < 0 ? `${t('piles_behind')} ${Math.abs(kpiDiff).toFixed(1)}%` : `${t('piles_ahead')} ${kpiDiff.toFixed(1)}%`}
          trend={kpiDiff < 0 ? "down" : "up"} 
          icon={<TrendingUp className="text-white w-6 h-6"/>}
          color={kpiDiff < 0 ? "bg-rose-600" : "bg-emerald-600"}
        />
        <KPICard 
          title={t('payment_value')} 
          value="4.55 B" 
          subtext={t('payment_waiting')} 
          trend="neutral" 
          icon={<Wallet className="text-white w-6 h-6"/>}
          color="bg-blue-600"
        />
        <KPICard 
          title={t('risks')} 
          value="4" 
          subtext="2 Major, 2 Minor" 
          trend="down" 
          icon={<AlertOctagon className="text-white w-6 h-6"/>}
          color="bg-amber-500"
        />
      </div>

      {loading && (
          <div className="flex items-center gap-2 text-sm text-blue-600 bg-blue-50 p-3 rounded-xl w-fit animate-pulse border border-blue-100">
              <RefreshCw className="w-4 h-4 animate-spin"/> {t('updating_data')}
          </div>
      )}

      <div className="flex flex-col gap-8">
            <div className="bg-white p-4 md:p-8 rounded-2xl shadow-sm border border-slate-200 w-full overflow-hidden">
                <h3 className="font-bold text-slate-800 text-lg mb-6 flex items-center gap-2">
                    <TrendingUp className="w-5 h-5 text-blue-600" /> {t('d800_progress')}
                </h3>
                <div className="h-[350px] md:h-[450px] w-full">
                    <ResponsiveContainer width="100%" height="100%">
                        <ComposedChart data={d800Data} margin={{ top: 20, bottom: 20, left: 10, right: 10 }}>
                            <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                            <XAxis dataKey="date" tick={{fontSize: 10, fill: '#94a3b8'}} axisLine={false} tickLine={false} interval="preserveStartEnd" minTickGap={40} />
                            <YAxis tick={{fontSize: 11, fill: '#94a3b8'}} axisLine={false} tickLine={false} label={{ value: t('unit_piles'), angle: -90, position: 'insideLeft', style: {fontSize: '11px', fill: '#94a3b8'} }} />
                            <Tooltip contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }} />
                            <Legend verticalAlign="bottom" align="center" wrapperStyle={{fontSize: '12px', paddingTop: '20px'}}/>
                            <Line type="monotone" dataKey="plan" stroke="#3b82f6" strokeWidth={3} dot={false} name={`${t('plan')} (${t('unit_piles').toLowerCase()})`} >
                                <LabelList content={<LastPointLabel lastValidIndex={lastD800PlanIndex} color="#3b82f6" unit="" isInteger={true} />} dataKey="plan" />
                            </Line>
                            <Line type="monotone" dataKey="actual" stroke="#ef4444" strokeWidth={3} dot={false} name={`${t('actual')} (${t('unit_piles').toLowerCase()})`}>
                                <LabelList content={<LastPointLabel lastValidIndex={lastD800ActualIndex} color="#ef4444" unit="" isInteger={true} />} dataKey="actual" />
                            </Line>
                            <Line type="monotone" dataKey="forecast" stroke="#10b981" strokeDasharray="5 5" strokeWidth={2} dot={false} name={`${t('forecast')} (${t('unit_piles').toLowerCase()})`}>
                                <LabelList content={<LastPointLabel lastValidIndex={lastD800ForecastIndex} color="#10b981" unit="" isInteger={true} />} dataKey="forecast" />
                            </Line>
                        </ComposedChart>
                    </ResponsiveContainer>
                </div>
            </div>

            <div className="bg-white p-4 md:p-8 rounded-2xl shadow-sm border border-slate-200 w-full overflow-hidden">
                <h3 className="font-bold text-slate-800 text-lg mb-6 flex items-center gap-2">
                    <Wallet className="w-5 h-5 text-emerald-600" /> {t('payment_progress_title')}
                </h3>
                <div className="h-[350px] md:h-[450px] w-full">
                    <ResponsiveContainer width="100%" height="100%">
                        <ComposedChart data={paymentData} margin={{ top: 20, bottom: 20, left: 10, right: 10 }}>
                            <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                            <XAxis dataKey="date" tick={{fontSize: 10, fill: '#94a3b8'}} axisLine={false} tickLine={false} interval="preserveStartEnd" minTickGap={40} />
                            <YAxis domain={[0, 100]} tick={{fontSize: 11, fill: '#94a3b8'}} axisLine={false} tickLine={false} />
                            <Tooltip contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }} />
                            <Legend verticalAlign="bottom" align="center" wrapperStyle={{fontSize: '12px', paddingTop: '20px'}}/>
                            <Line type="monotone" dataKey="progress" stroke="#ef4444" strokeWidth={3} dot={false} name={`${t('dashboard')} (%)`}>
                                <LabelList content={<LastPointLabel lastValidIndex={lastProgressIndex} color="#ef4444" unit="%" />} dataKey="progress" />
                            </Line>
                            <Line type="monotone" dataKey="payment" stroke="#3b82f6" strokeWidth={3} dot={false} name={`${t('payment')} (%)`}>
                                <LabelList content={<LastPointLabel lastValidIndex={getLastValidIndex(paymentData, 'payment')} color="#3b82f6" unit="%" />} dataKey="payment" />
                            </Line>
                        </ComposedChart>
                    </ResponsiveContainer>
                </div>
            </div>
      </div>

      <div className="bg-white p-6 md:p-8 rounded-2xl shadow-sm border border-slate-200 w-full overflow-hidden">
          <div className="flex items-center justify-between mb-6">
              <h3 className="font-bold text-slate-800 text-lg flex items-center gap-2">
                  <Users className="w-5 h-5 text-orange-500" /> {t('manpower')} ({t('last_updated')})
              </h3>
              <div className="flex gap-4">
                  <div className="flex items-center gap-2 text-xs text-slate-500 font-medium">
                      <div className="w-3 h-3 bg-slate-500 rounded-sm"></div> {t('workers')}
                  </div>
                  <div className="flex items-center gap-2 text-xs text-slate-500 font-medium">
                      <div className="w-3 h-3 bg-orange-400 rounded-sm"></div> {t('engineers')}
                  </div>
              </div>
          </div>
          <div className="h-[300px] md:h-[400px] w-full">
               <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={manpowerData} margin={{ top: 20, right: 10, left: -20, bottom: 20 }}>
                      <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                      <XAxis dataKey="date" tick={{fontSize: 10, fill: '#64748b'}} axisLine={false} tickLine={false} interval="preserveStartEnd" minTickGap={20} />
                      <YAxis tick={{fontSize: 10, fill: '#64748b'}} axisLine={false} tickLine={false} />
                      <Tooltip cursor={{fill: '#f8fafc'}} contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }} />
                      <Bar dataKey="workers" stackId="a" fill="#64748b" name={t('workers')}>
                         <LabelList dataKey="workers" position="inside" fill="#fff" fontSize={10} fontWeight="bold" />
                      </Bar>
                      <Bar dataKey="engineers" stackId="a" fill="#f59e0b" name={t('engineers')} radius={[4, 4, 0, 0]}>
                         <LabelList dataKey="engineers" position="inside" fill="#fff" fontSize={10} fontWeight="bold" />
                      </Bar>
                  </BarChart>
              </ResponsiveContainer>
          </div>
      </div>

      <div className="bg-slate-50/50 border border-slate-200 rounded-3xl p-8 md:p-12 shadow-sm">
          <div className="flex flex-col items-center text-center space-y-6">
              <div className="p-4 bg-slate-100 rounded-full"><FolderOpen className="w-10 h-10 text-slate-600" /></div>
              <div className="space-y-2">
                  <h3 className="text-2xl font-black text-slate-800 tracking-tight">{t('site_photos')}</h3>
                  <p className="text-slate-500 max-w-lg text-sm leading-relaxed">{t('site_photos_desc')}</p>
