              <a href={driveFolderUrl} target="_blank" rel="noopener noreferrer" className="flex items-center gap-3 px-10 py-4 bg-blue-600 text-white rounded-2xl font-black text-lg hover:bg-blue-700 transition-all shadow-xl shadow-blue-200 hover:scale-105 active:scale-95 group">
                  {t('open_drive')} <ExternalLink className="w-5 h-5 group-hover:translate-x-1 group-hover:-translate-y-1 transition-transform" />
              </a>
          </div>
      </div>
    </div>
  );
};

