import { Home, RefreshCw, ExternalLink, FolderOpen } from 'lucide-react';
import { Language } from '../types';
import { TRANSLATIONS } from '../constants';

interface ModelHouseProps {
    data: any[];
    loading: boolean;
    error: boolean;
    language: Language;
}

const LastPointLabel = (props: any) => {
  const { x, y, value, index, lastValidIndex, color, unit } = props;
  if (index === lastValidIndex && value !== null && value !== undefined) {
    return (
      <g>
        <circle cx={x} cy={y} r={6} fill={color} stroke="#fff" strokeWidth={3} />
        <text x={x} y={y} dy={-15} fill={color} fontSize={13} fontWeight="bold" textAnchor="middle">
          {Number(value).toFixed(1)}{unit || ''}
        </text>
      </g>
    );
  }
  return null;
};

const ModelHouse: React.FC<ModelHouseProps> = ({ data, loading, error, language }) => {
  const t = (key: string) => TRANSLATIONS[language][key] || key;
  const driveFolderUrl = "https://drive.google.com/drive/folders/1I4GCEJ_PoSmCA7AvOBCiAoN8xjlVH8f1";

  const getLastValidIndex = (key: string) => {
      for (let i = data.length - 1; i >= 0; i--) {
          if (data[i][key] !== null && data[i][key] !== undefined) return i;
      }
      return -1;
  };

  const lastPlanIndex = getLastValidIndex('plan');
  const lastActualIndex = getLastValidIndex('actual');

  return (
    <div className="p-4 md:p-8 max-w-7xl mx-auto space-y-8 animate-fade-in pb-20">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div className="flex items-center gap-4">
            <div className="bg-blue-600 p-3 rounded-xl shadow-lg"><Home className="w-6 h-6 text-white" /></div>
            <div>
                <h2 className="text-2xl font-bold text-slate-800">{t('model_house')}</h2>
                <p className="text-slate-500 text-sm font-medium">{t('model_house_desc')}</p>
            </div>
        </div>
      </div>

      <div className="bg-white p-4 md:p-6 rounded-2xl shadow-sm border border-slate-200">
        <div className="flex justify-between items-center mb-6">
            <h3 className="font-bold text-slate-800 text-lg">{t('chart_progress')}</h3>
            <span className="text-xs font-bold text-slate-400 bg-slate-100 px-3 py-1 rounded-full uppercase tracking-wider">{t('unit_percent')}</span>
        </div>

        <div className="h-[350px] md:h-[450px] w-full">
            {loading && data.length === 0 ? (
                <div className="h-full w-full flex items-center justify-center bg-slate-50 rounded-xl animate-pulse">
                    <RefreshCw className="w-8 h-8 text-blue-400 animate-spin" />
                </div>
            ) : (
                <ResponsiveContainer width="100%" height="100%">
                    <ComposedChart data={data} margin={{ top: 35, right: 30, left: 0, bottom: 20 }}>
                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                        <XAxis dataKey="month" tick={{fontSize: 12, fill: '#64748b'}} axisLine={false} tickLine={false} dy={10} />
                        <YAxis tick={{fontSize: 12, fill: '#64748b'}} domain={[0, 100]} ticks={[0, 25, 50, 75, 100]} axisLine={false} tickLine={false} dx={-5} />
                        <Tooltip contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }} formatter={(value: any) => [`${value}%`, '']} />
                        <Legend verticalAlign="bottom" align="center" height={36} iconType="circle" wrapperStyle={{ paddingTop: '20px' }} />
                        <Line type="monotone" dataKey="plan" stroke="#3b82f6" strokeWidth={4} dot={false} name={`${t('plan')} (%)`} >
                            <LabelList content={<LastPointLabel lastValidIndex={lastPlanIndex} color="#3b82f6" unit="%" />} dataKey="plan" />
                        </Line>
                        <Line type="monotone" dataKey="actual" stroke="#ef4444" strokeWidth={4} dot={false} name={`${t('actual')} (%)`}>
                            <LabelList content={<LastPointLabel lastValidIndex={lastActualIndex} color="#ef4444" unit="%" />} dataKey="actual" />
                        </Line>
                    </ComposedChart>
                </ResponsiveContainer>
            )}
        </div>
      </div>

      <div className="bg-slate-50/50 border border-slate-200 p-8 md:p-12 rounded-3xl flex flex-col items-center text-center space-y-6 shadow-sm">
          <div className="p-4 bg-slate-100 rounded-full"><FolderOpen className="w-10 h-10 text-slate-600" /></div>
          <div className="space-y-2">
              <h3 className="text-2xl font-black text-slate-800 tracking-tight">{t('view_photos')}</h3>
              <p className="max-w-md text-slate-500 text-sm leading-relaxed">{t('site_photos_desc')}</p>
          </div>
          <a href={driveFolderUrl} target="_blank" rel="noopener noreferrer" className="mt-4 px-10 py-4 bg-blue-600 text-white rounded-2xl font-black hover:bg-blue-700 transition-all flex items-center gap-3 shadow-xl shadow-blue-200 hover:scale-105 active:scale-95 group">
              {t('open_drive')} <ExternalLink className="w-5 h-5 group-hover:translate-x-1 group-hover:-translate-y-1 transition-transform" />
          </a>
      </div>
    </div>
  );
};

export default ModelHouse;

import React, { useState, useEffect } from 'react';
// Add PROJECT_NAME to the imports from constants
import { PROJECT_NAME, PROJECT_SPECS, MANAGEMENT_TEAM, MILESTONES, SAFETY_START_DATE, PROJECT_OVERVIEW, LOGO_URL, RENDER_URL, TRANSLATIONS } from '../constants';
import { Clock, ShieldCheck, Ruler, Layers, ArrowUp, Building2, MapPin, Building, Phone, CheckCircle2 } from 'lucide-react';
import { Language } from '../types';

interface GeneralInfoProps {
  language: Language;
}

const GeneralInfo: React.FC<GeneralInfoProps> = ({ language }) => {
  const [safetyHours, setSafetyHours] = useState(0);
  const t = (key: string) => TRANSLATIONS[language][key] || key;

  useEffect(() => {
    const calculateSafetyHours = () => {
      const start = new Date(SAFETY_START_DATE).getTime();
      const now = new Date().getTime();
      const diff = now - start;
      if (diff < 0) return 0;
      return Math.floor(diff / (1000 * 60 * 60));
    };

    setSafetyHours(calculateSafetyHours());
    const interval = setInterval(() => {
        setSafetyHours(calculateSafetyHours());
    }, 60000);

    return () => clearInterval(interval);
  }, []);

  return (
    <div className="p-8 max-w-7xl mx-auto space-y-8 animate-fade-in">
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

        <div className="lg:col-span-2 space-y-8">
            {/* 1. Main Visual */}
            <div className="relative rounded-2xl overflow-hidden shadow-lg h-[400px] group border border-slate-200">
                <img 
                    src={RENDER_URL} 
                    alt="Project Render" 
                    className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-700"
                />
                <div className="absolute bottom-0 left-0 p-8 w-full bg-gradient-to-t from-slate-900/90 via-slate-900/40 to-transparent flex items-end gap-6">
                    <div className="w-24 h-24 bg-white rounded-lg flex items-center justify-center shadow-xl ring-2 ring-white/20 shrink-0 overflow-hidden p-2">
                        <img 
                            src={LOGO_URL}
                            alt="Logo" 
                            className="w-full h-full object-contain" 
                        />
                    </div>
                    <div className="mb-1">
                         <h2 className="text-3xl font-bold text-white tracking-wide uppercase">{PROJECT_NAME}</h2>
                         <div className="h-1 w-20 bg-blue-500 rounded mt-2"></div>
                    </div>
                </div>
            </div>

            {/* 2. Overview */}
            <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6">
                <h3 className="text-lg font-bold text-slate-800 mb-6 flex items-center gap-2 border-b border-slate-100 pb-2">
                    <Building className="w-5 h-5 text-blue-600"/> {t('project_overview')}
                </h3>
                <div className="space-y-4">
                    <OverviewItem label={t('investor')} value={PROJECT_OVERVIEW.investor} isUppercase highlight />
                    <OverviewItem label={t('project_name')} value={PROJECT_OVERVIEW.projectName} />
                    <OverviewItem label={t('location')} value={PROJECT_OVERVIEW.location} icon={<MapPin className="w-4 h-4 text-slate-400 mt-0.5 flex-shrink-0"/>} />
                </div>
            </div>

            {/* 3. Specs */}
            <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6">
                <h3 className="text-lg font-bold text-slate-800 mb-6 flex items-center gap-2 border-b border-slate-100 pb-2">
                    <Layers className="w-5 h-5 text-blue-600"/> {t('specifications')}
                </h3>
                <ul className="space-y-4">
                    <SpecItem label={t('spec_depth')} value={PROJECT_SPECS.depth} icon={<ArrowUp className="rotate-180 w-4 h-4"/>} />
                    <SpecItem label={t('spec_height')} value={PROJECT_SPECS.height} icon={<ArrowUp className="w-4 h-4"/>} />
                    <SpecItem label={t('spec_land_area')} value={PROJECT_SPECS.landArea} icon={<Ruler className="w-4 h-4"/>} />
                    <SpecItem label={t('spec_density')} value={PROJECT_SPECS.buildingDensity} icon={<Building className="w-4 h-4"/>} />
                    <SpecItem label={t('spec_ratio')} value={PROJECT_SPECS.floorAreaRatio} icon={<Layers className="w-4 h-4"/>} />
                    <SpecItem label={t('spec_gfa_1')} value={PROJECT_SPECS.areaGround} icon={<Ruler className="w-4 h-4"/>} />
                    <SpecItem label={t('spec_gfa_no_base')} value={PROJECT_SPECS.areaTotalNoBasement} icon={<Layers className="w-4 h-4"/>} />
                    <SpecItem label={t('spec_gfa_base')} value={PROJECT_SPECS.areaTotalWithBasement} icon={<Layers className="w-4 h-4"/>} />
                    <SpecItem label={t('spec_floors')} value={PROJECT_SPECS.floors[language]} icon={<Building2 className="w-4 h-4"/>} />
                </ul>
            </div>

            {/* 4. Team */}
            <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6">
                <h3 className="text-lg font-bold text-slate-800 mb-6 flex items-center gap-2 border-b border-slate-100 pb-2">
                    <CheckCircle2 className="w-5 h-5 text-blue-600"/> {t('pm_team')}
                </h3>
                <div className="overflow-x-auto">
                    <table className="w-full text-left">
                        <thead className="bg-slate-50">
                            <tr>
                                <th className="p-4 text-xs font-bold text-slate-500 uppercase tracking-wider w-1/3">{t('team_name')}</th>
                                <th className="p-4 text-xs font-bold text-slate-500 uppercase tracking-wider w-1/4">{t('team_role')}</th>
                                <th className="p-4 text-xs font-bold text-slate-500 uppercase tracking-wider">{t('team_contact')}</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-100">
                            {MANAGEMENT_TEAM.map((member, idx) => (
                                <tr key={idx} className="hover:bg-slate-50 transition-colors">
                                    <td className="p-4 font-semibold text-slate-900">{member.name}</td>
                                    <td className="p-4">
                                         <span className="inline-flex items-center px-2.5 py-0.5 rounded font-medium bg-blue-100 text-blue-800 text-sm">
                                            {member.role}
                                         </span>
                                    </td>
                                    <td className="p-4 text-slate-600 text-sm font-mono">{member.contact}</td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>

        <div className="lg:col-span-1 space-y-8">
            <div className="bg-gradient-to-br from-emerald-600 to-teal-700 rounded-2xl p-8 text-white shadow-lg flex flex-col items-center justify-center text-center relative overflow-hidden">
                <ShieldCheck className="w-32 h-32 absolute -right-6 -top-6 text-white/10" />
                <h3 className="text-lg font-medium mb-4 uppercase tracking-wider border-b border-white/20 pb-2 w-full">{t('safety')}</h3>
                <div className="text-5xl font-bold mb-2 font-mono tracking-tighter">{safetyHours.toLocaleString()}</div>
                <p className="text-emerald-100 font-medium">{t('safety_hours')}</p>
                <div className="mt-4 px-3 py-1 bg-white/10 rounded-full text-xs text-emerald-50">{t('safety_since')}</div>
            </div>

            <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6 sticky top-8">
                <h3 className="text-lg font-bold text-slate-800 mb-6 flex items-center gap-2 border-b border-slate-100 pb-2">
                    <Clock className="w-5 h-5 text-blue-600"/> {t('milestones')}
                </h3>
                <div className="relative border-l-2 border-slate-200 ml-3 space-y-8 py-2">
                    {MILESTONES.map((milestone, idx) => (
                        <div key={idx} className="relative pl-8 group">
                            <div className={`absolute -left-[9px] top-1.5 w-4 h-4 rounded-full border-2 transition-colors duration-300 ${milestone.completed ? 'bg-green-500 border-green-500' : 'bg-white border-slate-300 group-hover:border-blue-400'}`}></div>
                            <div className="flex flex-col gap-1">
                                <span className="text-xs font-bold text-blue-600 uppercase tracking-wide">{milestone.date}</span>
                                <span className="text-sm font-medium text-slate-800 leading-snug">{milestone.description[language]}</span>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        </div>
      </div>
    </div>
  );
};

const SpecItem = ({ label, value, icon }: any) => (
    <div className="flex justify-between items-start border-b border-slate-100 pb-2 last:border-0 hover:bg-slate-50 px-2 rounded transition-colors">
        <span className="text-slate-500 flex items-center gap-2 text-sm">{icon} {label}</span>
        <span className="font-medium text-slate-900 text-right text-sm max-w-[50%]">{value}</span>
    </div>
)

const OverviewItem = ({ label, value, icon, isUppercase, highlight }: any) => (
    <div className="grid grid-cols-1 md:grid-cols-3 gap-2 border-b border-slate-100 pb-3 last:border-0">
        <span className="text-slate-500 text-sm font-medium flex items-start gap-2 col-span-1">{label}</span>
        <div className={`col-span-2 text-slate-900 flex items-start gap-2 ${highlight ? 'font-bold' : 'font-medium'} ${isUppercase ? 'uppercase' : ''}`}>
             {icon && <span className="mt-0.5">{icon}</span>}
             <span>{value}</span>
        </div>
    </div>
)

export default GeneralInfo;
